window.ghPrintPdf = function(doc) {
  let url;
  try {
    url = URL.createObjectURL(doc.output("blob"));
  } catch (e) {
    console.error("Could not prepare PDF for printing", e);
    if (window.toast) toast("Could not prepare document for printing", "error");
    return;
  }
  const isIOS = /iPad|iPhone|iPod/.test(navigator.userAgent) || navigator.platform === "MacIntel" && navigator.maxTouchPoints > 1;
  const openTab = () => {
    const w = window.open(url, "_blank");
    if (!w && window.toast) toast("Pop-up blocked \u2014 allow pop-ups to print", "error");
  };
  if (isIOS) {
    openTab();
    return;
  }
  const f = document.createElement("iframe");
  f.style.cssText = "position:fixed;left:-10000px;top:0;width:800px;height:1100px;border:0;visibility:hidden";
  f.onload = () => {
    setTimeout(() => {
      try {
        f.contentWindow.focus();
        f.contentWindow.print();
      } catch (e) {
        console.warn("Frame print failed, opening in tab", e);
        openTab();
      }
    }, 350);
    setTimeout(() => {
      URL.revokeObjectURL(url);
      f.remove();
    }, 12e4);
  };
  f.src = url;
  document.body.appendChild(f);
};
